#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

export GH_REPO=LeoPerez8/wave
WORKER_URL=https://wave-updates.leonardolp2424.workers.dev

ROOT=$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)
UPDATES="$ROOT/apps/updates"
MOBILE="$ROOT/apps/mobile"
# The branch this checkout is on, so the wizard survives its feature branch landing.
BRANCH=$(git -C "$ROOT" symbolic-ref --quiet --short HEAD) || {
  warn "This checkout isn't on a branch. Check one out and run this again."
  exit 1
}
wrangler() { (cd "$UPDATES" && pnpm exec wrangler "$@"); }

banner "Wave update service setup"

stage "Check this machine"
say "Every install then takes one APK by hand, so run this once before sharing that APK."
gh auth status >/dev/null 2>&1 || { warn "gh isn't signed in. Run: gh auth login"; exit 1; }
gh secret list >/dev/null || { warn "gh can't read $GH_REPO's secrets; this needs an admin of the repo."; exit 1; }
git -C "$ROOT" pull -q --ff-only origin "$BRANCH" || { warn "This checkout can't follow $BRANCH."; exit 1; }
[[ -d "$UPDATES/node_modules" && -d "$MOBILE/node_modules" ]] || (cd "$ROOT" && pnpm install --frozen-lockfile)
pause "All set. Press Enter."

stage "Sign in to Cloudflare"
say "Use the account whose workers.dev subdomain is leonardolp2424, the one with wave-sync."
open_url "https://dash.cloudflare.com/?to=/:account/r2"
step "If the R2 page offers a plan, enable it. The free tier needs a card on file."
pause "Press Enter once R2 is enabled."
if ! wrangler whoami 2>/dev/null | grep -q "You are logged in"; then
  step "wrangler opens a sign-in page next. Allow it."
  wrangler login
fi
wrangler whoami
pause "Is that the right account? Press Enter, or Ctrl-C if not."

stage "Create the bucket"
say "Private: phones reach it only through the Worker."
if output=$(wrangler r2 bucket create wave-updates 2>&1); then
  printf '  %s✓ created%s wave-updates\n' "$GREEN" "$RESET"
elif grep -qi "already exists\|already own" <<<"$output"; then
  printf '  %s✓ already there%s wave-updates\n' "$GREEN" "$RESET"
else
  printf '%s\n' "$output"; warn "Couldn't create the bucket."; exit 1
fi
pause "Press Enter."

stage "Deploy the Worker"
(cd "$ROOT" && pnpm --filter @wave/updates run deploy)
say "Checking it answers. A check with no headers should get 400."
sleep 5
code=$(curl -s -o /dev/null -w '%{http_code}' "$WORKER_URL/v1/manifest" || true)
if [[ "$code" == 400 ]]; then
  printf '  %s✓ answering%s %s\n' "$GREEN" "$RESET" "$WORKER_URL"
else
  warn "$WORKER_URL/v1/manifest answered $code, not 400."
  warn "If the deploy printed another address, apps/mobile/app.config.ts and UPDATES_ORIGIN must change."
  pause "Press Enter to go on, or Ctrl-C to stop."
fi
pause "Press Enter."

stage "Give CI access to the bucket"
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Custom token → Get started."
step "Name it wave-updates-ci."
step "Permissions: Account · Workers R2 Storage · Edit."
step "Account Resources: Include · your account. Continue to summary → Create Token."
step "Copy the token. Cloudflare shows it once."
ask_secret CLOUDFLARE_API_TOKEN "Paste the token:"
say "The account id is on the right of the account's Workers & Pages page, or in whoami above."
ask CLOUDFLARE_ACCOUNT_ID "Paste the account id:"
buckets=$(curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
  "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/r2/buckets" || true)
if grep -q '"wave-updates"' <<<"$buckets"; then
  printf '  %s✓ the token can see%s wave-updates\n' "$GREEN" "$RESET"
else
  warn "That token and id can't see wave-updates, so nothing was saved. Run this again."
  exit 1
fi
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
unset CLOUDFLARE_API_TOKEN
pause "Press Enter."

stage "Create the signing key"
say "CI signs each update, and an APK runs only what its certificate accepts."
CERT="$MOBILE/certs/certificate.pem"
generate=yes
if [[ -f "$CERT" ]] && gh secret list | grep -q '^UPDATES_SIGNING_KEY'; then
  printf '  %s✓ already set up%s certificate and UPDATES_SIGNING_KEY\n' "$GREEN" "$RESET"
  generate=no
elif [[ -f "$CERT" ]] || gh secret list | grep -q '^UPDATES_SIGNING_KEY'; then
  warn "Only one half of the pair exists, so a new pair replaces it."
  warn "Installs built with the old certificate get no more updates until they install an APK."
  confirm "Make a new pair?" || generate=no
fi
if [[ "$generate" == yes ]]; then
  keys=$(mktemp -d)
  trap 'rm -rf "$keys"' EXIT
  rm -f "$CERT"
  (cd "$MOBILE" && pnpm exec expo-updates codesigning:generate \
    --key-output-directory "$keys" \
    --certificate-output-directory certs \
    --certificate-validity-duration-years 30 \
    --certificate-common-name "Wave")
  gh secret set UPDATES_SIGNING_KEY <"$keys/private-key.pem"
  WRITTEN_SECRET+=(UPDATES_SIGNING_KEY)
  printf '  %s✓ set%s GitHub secret UPDATES_SIGNING_KEY\n' "$GREEN" "$RESET"
  rm -rf "$keys"
fi
# Apart from making the pair, so a run that declined the commit, or stopped there, offers it again.
if [[ -n "$(git -C "$ROOT" status --porcelain -- apps/mobile/certs/certificate.pem)" ]]; then
  say "The certificate is public and goes in the repo. Pushing it starts a new full APK."
  if confirm "Commit and push it to $BRANCH?"; then
    git -C "$ROOT" add apps/mobile/certs/certificate.pem
    git -C "$ROOT" commit -qm "chore: add the update signing certificate" -- apps/mobile/certs/certificate.pem
    git -C "$ROOT" push -q origin "HEAD:$BRANCH"
    printf '  %s✓ pushed%s the certificate\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("Commit apps/mobile/certs/certificate.pem to $BRANCH")
  fi
fi
pause "Press Enter."

finish
note "Wave's next full APK holds the certificate. Install that one by hand."
note "Check the secrets with: gh secret list"
